<?php $this->layout('default'); use Moves\Services\CmsAudit; use Moves\Services\CmsBroadcasts as B; use Moves\Services\ExternalNotifications as X; use Moves\Support\CmsView as V;
B::dispatchDue(); $rows = B::listing(); $queue = X::recent(); $recent = CmsAudit::listing([], 1, 15); $tab = V::queryString('aba'); $pending = count(array_filter($queue, static fn ($q) => $q['status'] === 'pending')); ?>
<?= V::tabs([['/comunicacoes', 'Mensagens', count($rows), $tab === ''], ['?aba=fila', 'Fila de envio', $pending, $tab === 'fila'], ['?aba=alteracoes', 'Alterações recentes', count($recent['rows']), $tab === 'alteracoes']], 'Central de notificações') ?>
<?php if ($tab === 'fila'): ?><section class="cms-list"><?= V::listHead('Fila de envio', 'E-mail e Telegram saem pelo processador agendado') ?><?php if ($queue === []): ?><?= V::empty('Nenhum envio externo registrado.') ?><?php else: ?><div class="cms-table-wrap"><table><thead><tr><th>Canal</th><th>Evento</th><th>Status</th><th class="num">Tentativas</th><th>Erro</th></tr></thead><tbody><?php foreach ($queue as $q): ?><tr><td><?= V::e($q['channel']) ?></td><td><code class="cms-chip"><?= V::e($q['dedupe_key']) ?></code></td><td><?= V::badge($q['status'] === 'sent' ? 'active' : ($q['status'] === 'failed' ? 'failed' : 'pending'), $q['status']) ?></td><td class="num"><?= (int) $q['attempts'] ?></td><td><?= V::e($q['last_error'] ?? '') ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<?php elseif ($tab === 'alteracoes'): ?><section class="cms-card"><?php foreach ($recent['rows'] as $l): ?><div class="cms-row"><div><strong><?= V::e($l['event_type']) ?></strong><br><small><?= V::e($l['actor_email'] ?? 'Sistema') ?> · <?= V::date($l['created_at']) ?></small></div></div><?php endforeach; ?><?= $recent['rows'] === [] ? V::empty('Nenhuma alteração.') : '' ?></section>
<?php else: ?><div class="cms-form-list"><form class="cms-card" method="post" action="/acao/broadcast-send" data-confirm="Registrar esta comunicação para os destinatários escolhidos?"><header class="cms-card-head"><h2>Enviar comunicação</h2><?= V::icon('send') ?></header><?= V::csrf() ?><?= V::field('Título/assunto *', 'title', '', ['required' => true]) ?><?= V::field('Mensagem *', 'body', '', ['type' => 'textarea', 'rows' => 5, 'required' => true]) ?><div class="cms-form-grid"><?= V::field('Destinatários', 'audience', 'all', ['type' => 'select', 'choices' => B::AUDIENCES]) ?><?= V::field('Canal de envio', 'channel', 'internal', ['type' => 'select', 'choices' => B::CHANNELS, 'help' => 'O e-mail depende do canal ativo em Configurações de notificações.']) ?><?= V::field('Prioridade', 'priority', 'info', ['type' => 'select', 'choices' => B::PRIORITIES]) ?><?= V::field('Link ao clicar', 'link', '', ['help' => 'Opcional. Comece com / ou https://']) ?><?= V::field('Agendar para', 'scheduled_at', '', ['type' => 'datetime-local', 'help' => 'Vazio envia agora.']) ?><?= V::field('Expirar em', 'expires_at', '', ['type' => 'datetime-local', 'help' => 'Opcional.']) ?></div><button class="cms-btn-primary" style="width:100%"><?= V::icon('send') ?>Enviar ou agendar</button></form>
<section class="cms-card"><header class="cms-card-head"><h2>Mensagens cadastradas</h2><b class="cms-count"><?= count($rows) ?></b></header><?php if ($rows === []): ?><?= V::empty('Nenhuma mensagem cadastrada.') ?><?php endif; foreach ($rows as $b): ?><div class="cms-row"><div><strong><?= V::e($b['title']) ?></strong> <?= V::badge($b['status'] === 'sent' ? 'active' : ($b['status'] === 'scheduled' ? 'pending' : 'neutral'), B::STATUS[$b['status']] ?? '') ?><br><small><?= V::e(B::AUDIENCES[$b['audience']] ?? '') ?> · <?= V::date($b['scheduled_at']) ?> · <?= (int) $b['read_count'] ?>/<?= (int) $b['recipients'] ?> lidas</small></div><?php if ($b['status'] === 'scheduled'): ?><?= V::actionButton('broadcast-cancel', 'Cancelar', ['id' => $b['id']], 'cms-btn-danger', 'Cancelar esta comunicação?') ?><?php endif; ?></div><?php endforeach; ?></section></div><?php endif; ?>
